const note = sticky("## CEO Brain — Website Intelligence (internal agent, ADR-3)\nCalled by Lead Intake with John's hand-off (same inputs as the Website Builder). Never talks to the customer.\n\nFlow: plan 6 queries → Web Search (Browserbase, n8n gateway credits) → identify the company (John's/customer's URL wins; else best match; low confidence = no site facts) → fetch homepage + up to 3 pages → digest with a labelled fact ledger (VERIFIED_PUBLIC_FACT / JOHN_OR_CUSTOMER_PROVIDED_FACT / THIRD_PARTY_PUBLIC_INFORMATION / INFERENCE / UNKNOWN) → Ryan's role prompt live from the vault → Claude (deterministic fallback when the model is unavailable) → WEBSITE_CREATOR_BRIEF (JSON + text, two variations, placeholders, creator instruction) → run + audit → Hand Off to Website Builder (research_brief, research_json) → event to the Orchestrator (website.research, or website.info_needed with questions for John).\n\nRule 12: a mock-up is never delayed for missing information. Source of truth: ryan/ceo-brain/workflows/website-intelligence/build.js — do not hand-edit Code nodes.", [whenCalled, plan, search, identify], { color: 4 });

export default workflow('ceo-brain-website-intelligence', 'CEO Brain — Website Intelligence')
  .add(whenCalled)
  .to(plan)
  .to(search)
  .to(identify)
  .to(fetchHome)
  .to(pickPages)
  .to(fetchPages)
  .to(digest)
  .to(loadRole)
  .to(compose)
  .to(claude.to(finalize))
  .add(claude.onError(finalize))
  .add(finalize)
  .to(logRun)
  .to(logAudit)
  .to(infoGate
    .onTrue(saveInfoTask.to(askGate))
    .onFalse(readyGate))
  .add(askGate
    .onTrue(saveAskMsg.to(sendAsk.to(readyGate)))
    .onFalse(readyGate))
  .add(readyGate
    .onTrue(handOff.to(notify))
    .onFalse(notify))
  .add(note);
